const FCityResidentialEntrance* CityCommercialEntrances::Find(const FString& MeshName)
{
    for (const auto& Entry : All())
        if (MeshName == Entry.OriginalMesh || MeshName == FPaths::GetBaseFilename(Entry.TargetMesh)) return &Entry;
    return nullptr;
}
